        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)CombatStyle_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)CombatStyle_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.CSMD:
                {
                    _CSMDLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSMD;
                }
                case RecordTypeInts.CSRA:
                {
                    _CSRALocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSRA;
                }
                case RecordTypeInts.CSCV:
                {
                    _CSCVLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSCV;
                }
                case RecordTypeInts.DATA:
                {
                    _DATALocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.DATA;
                }
                case RecordTypeInts.CSTD:
                {
                    _CSTDLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSTD;
                }
                case RecordTypeInts.CSCR:
                {
                    _CSCRLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSCR;
                }
                case RecordTypeInts.CSFL:
                {
                    _CSFLLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSFL;
                }
                case RecordTypeInts.CSGD:
                {
                    _CSGDLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSGD;
                }
                case RecordTypeInts.CSLR:
                {
                    _CSLRLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSLR;
                }
                case RecordTypeInts.CSME:
                {
                    _CSMELocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSME;
                }
                case RecordTypeInts.CSTG:
                {
                    _CSTGLocation = (stream.Position - offset);
                    return (int)CombatStyle_FieldIndex.CSTG;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
